            best_score = score
            best_move = (dx, dy)
        elif score == best_score:
            # tie-break: deterministic prefer smaller dx, then smaller dy
            if (dx, dy) < best_move:
                best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

